provider "aws" {
    region = "us-west-1"
}

resource "aws_s3_bucket" "a" {
  bucket = "test_bucket"
}

resource "aws_s3_bucket_policy" "b" {
  bucket = aws_s3_bucket.a.id
  policy = jsonencode({
    "Version" : "2012-10-17",
    "Id"      : "my_policy",
    "Statement" : [
      {
        "Sid"       : "IPAllow",
        "Effect"    : "Deny",
        "Principal" : "*",
        "Action"    : "s3:*",
        "Resource"  : "arn:aws:s3:::test_bucket/*",
        "Condition" : {
          "IpAddress" : { "aws:SourceIp" : "1.2.3.4/32" }
        }
      }
    ]
  })
}

responsePreview:
Description: This Terraform configuration creates an AWS S3 bucket with a deployable, DNS-compliant name derived from `my_bucket`. Since AWS S3 bucket names cannot contain underscores, the bucket is named using the prefix `my-bucket` plus a random suffix for global uniqueness. It also attaches an S3 bucket policy using `jsonencode` that includes a policy version, an identifier, and a deny statement blocking all S3 actions from a specific IP address.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the S3 bucket will be created."
  type        = string
  default     = "us-east-1"
}

variable "denied_ip_cidr" {
  description = "The specific IP address or CIDR block to deny access from."
  type        = string
  default     = "203.0.113.10/32"
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = "my-bucket-${random_id.bucket_suffix.hex}
